-- All examples roll back and reuse existing identities; never change Auth.
begin;
select set_config('qa.entries.owner',(select user_id::text from public.household_members where role='owner' order by joined_at limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('qa.entries.owner'),true);
select set_config('qa.entries.hh',public.create_household('QA finance entry management rollback')::text,true);
set local role authenticated;
do $$declare h uuid:=current_setting('qa.entries.hh')::uuid;r uuid;o uuid;paid uuid;skipped uuid;t uuid;t2 uuid;expected jsonb;newterms jsonb;oldfingerprint text;a uuid;b uuid;c uuid;preview jsonb;
begin
 insert into public.savings_goals(household_id,name,target_amount) values(h,'Goal A',1000) returning id into a;
 insert into public.savings_goals(household_id,name,target_amount) values(h,'Goal B',2000) returning id into b;
 insert into public.goal_contributions(household_id,goal_id,amount,contribution_date,created_by) values(h,a,100,'2000-03-01',auth.uid()) returning id into c;
 update public.goal_contributions set goal_id=b,amount=125.25,contribution_date='2000-04-01' where id=c and household_id=h;
 if (select sum(amount) from public.goal_contributions where household_id=h and goal_id=b)<>125.25 then raise exception 'Savings edit failed';end if;
 if jsonb_array_length(public.get_finance_fortnight_review(h,'2000-03-01','second')->'source'->'savings')<>0 then raise exception 'Savings edit left wrong period';end if;
 delete from public.goal_contributions where id=c and household_id=h;
 if exists(select 1 from public.goal_contributions where household_id=h and id=c) then raise exception 'Savings delete failed';end if;
 insert into public.recurring_transactions(household_id,description,amount,type,due_day,paid_by,is_shared) values(h,'Original bill',100,'expense',31,auth.uid(),true) returning id into r;
 insert into public.recurring_transaction_occurrences(household_id,recurring_transaction_id,period_month,due_date,status) values(h,r,'2000-03-01','2000-03-31','pending') returning id into o;
 insert into public.recurring_transaction_occurrences(household_id,recurring_transaction_id,period_month,due_date,status) values(h,r,'2000-04-01','2000-04-30','pending') returning id into paid;
 insert into public.recurring_transaction_occurrences(household_id,recurring_transaction_id,period_month,due_date,status) values(h,r,'2000-05-01','2000-05-31','skipped') returning id into skipped;
 t:=public.pay_finance_recurring_occurrence(h,paid,100,'2000-04-30');
 t2:=public.pay_finance_recurring_occurrence(h,paid,100,'2000-04-30');
 if t is distinct from t2 or (select count(*) from public.transactions where household_id=h)<>1 then raise exception 'Payment not idempotent';end if;
 select public.finance_recurring_terms(x) into expected from public.recurring_transactions x where id=r;
 oldfingerprint:=public.get_finance_fortnight_review(h,'2000-03-01','second')->>'fingerprint';
 newterms:=expected||'{"amount":175.25,"description":"Updated bill","due_day":15}'::jsonb;
 perform public.manage_finance_recurring(h,r,newterms,expected,false);
 if not exists(select 1 from public.recurring_transaction_occurrences where id=o and due_date='2000-03-15' and (details_snapshot->>'amount')::numeric=175.25) then raise exception 'Pending amount or date not updated';end if;
 if not exists(select 1 from public.recurring_transaction_occurrences where id=paid and status='paid' and due_date='2000-04-30' and (details_snapshot->>'amount')::numeric=100 and details_snapshot->>'description'='Original bill' and transaction_id=t) then raise exception 'Paid history changed';end if;
 if not exists(select 1 from public.recurring_transaction_occurrences where id=skipped and status='skipped' and due_date='2000-05-31' and (details_snapshot->>'amount')::numeric=100) then raise exception 'Skipped history changed';end if;
 if (select amount from public.transactions where id=t)<>100 then raise exception 'Editing recurrent rewrote payment';end if;
 if oldfingerprint=public.get_finance_fortnight_review(h,'2000-03-01','second')->>'fingerprint' then raise exception 'Pending change did not invalidate review';end if;
 begin perform public.manage_finance_recurring(h,r,newterms,expected,false);raise exception 'Stale form accepted';exception when serialization_failure then null;end;
 begin perform public.pay_finance_recurring_occurrence(h,o,100,'2000-03-31');raise exception 'Stale payment accepted';exception when serialization_failure then null;end;
 if (select count(*) from public.transactions where household_id=h)<>1 then raise exception 'Stale payment left a movement';end if;
 begin perform public.manage_finance_recurring(h,r,newterms||'{"amount":-1}'::jsonb,newterms,false);raise exception 'Negative amount accepted';exception when check_violation then null;end;
 begin perform public.manage_finance_recurring(h,r,newterms||'{"amount":1.001}'::jsonb,newterms,false);raise exception 'Fractional cent accepted';exception when check_violation then null;end;
 -- A deliberate correction of a paid movement updates its historical detail.
 update public.transactions set amount=110.50,description='Corrected actual bill' where id=t;
 if (select (details_snapshot->>'amount')::numeric from public.recurring_transaction_occurrences where id=paid)<>110.50 then raise exception 'Actual payment correction not reflected';end if;
 perform public.manage_finance_recurring(h,r,'{}'::jsonb,newterms,true);
 if (select active from public.recurring_transactions where id=r) or (select status from public.recurring_transaction_occurrences where id=o)<>'skipped' then raise exception 'Recurring retirement left pending obligations';end if;
 if (select status from public.recurring_transaction_occurrences where id=paid)<>'paid' or (select count(*) from public.transactions where household_id=h)<>1 then raise exception 'Retirement removed paid history';end if;
 begin perform public.pay_finance_recurring_occurrence(h,o,175.25,'2000-03-15');raise exception 'Retired payment accepted';exception when serialization_failure then null;end;
 preview:=public.get_finance_fortnight_review(h,'2000-04-01','second');
 if preview->'source'->'occurrences'->0->'details_snapshot'->>'description'<>'Corrected actual bill' then raise exception 'Review source lost paid detail';end if;
 if public.build_household_backup_snapshot(h)->'tables'->'recurring_transaction_occurrences'->0->'details_snapshot' is null then raise exception 'Details missing from backup';end if;
end$$;
select true as savings_crud_recurring_edits_paid_history_retirement_retry_staleness_and_backup_passed;
rollback;

begin;
select set_config('qa.entries.a',(select user_id::text from public.household_members where role='owner' order by joined_at limit 1),true);
select set_config('qa.entries.b',(select user_id::text from public.household_members where role='owner' and user_id<>current_setting('qa.entries.a')::uuid order by joined_at limit 1),true);
select set_config('request.jwt.claim.sub',current_setting('qa.entries.a'),true);
select set_config('qa.entries.hh',public.create_household('QA finance entry permissions rollback')::text,true);
insert into public.household_members(household_id,user_id,role) values(current_setting('qa.entries.hh')::uuid,current_setting('qa.entries.b')::uuid,'guest');
insert into public.household_member_access(household_id,user_id,module,access_level) values(current_setting('qa.entries.hh')::uuid,current_setting('qa.entries.b')::uuid,'finance','view');
set local role authenticated;
with created as (insert into public.recurring_transactions(household_id,description,amount,type,due_day,paid_by) values(current_setting('qa.entries.hh')::uuid,'Protected bill',100,'expense',15,auth.uid()) returning id) select set_config('qa.entries.recurring',id::text,true) from created;
with created as (insert into public.savings_goals(household_id,name,target_amount) values(current_setting('qa.entries.hh')::uuid,'Protected goal',1000) returning id) insert into public.goal_contributions(household_id,goal_id,amount,contribution_date,created_by) select current_setting('qa.entries.hh')::uuid,id,50,'2000-01-01',auth.uid() from created;
select set_config('request.jwt.claim.sub',current_setting('qa.entries.b'),true);
do $$declare h uuid:=current_setting('qa.entries.hh')::uuid;r uuid:=current_setting('qa.entries.recurring')::uuid;e jsonb;
begin
 select public.finance_recurring_terms(x) into e from public.recurring_transactions x where id=r;
 if e is null then raise exception 'View permission lost';end if;
 begin perform public.manage_finance_recurring(h,r,e,e,false);raise exception 'Read-only recurring write accepted';exception when insufficient_privilege then null;end;
 begin perform public.pay_finance_recurring_occurrence(h,gen_random_uuid(),100,'2000-01-01');raise exception 'Read-only payment accepted';exception when insufficient_privilege then null;end;
 update public.goal_contributions set amount=999 where household_id=h;
 delete from public.goal_contributions where household_id=h;
 if (select sum(amount) from public.goal_contributions where household_id=h)<>50 then raise exception 'Read-only savings mutation accepted';end if;
end$$;
reset role;
update platform_security.household_controls set status='archived' where household_id=current_setting('qa.entries.hh')::uuid;
select set_config('request.jwt.claim.sub',current_setting('qa.entries.a'),true);
set local role authenticated;
do $$declare h uuid:=current_setting('qa.entries.hh')::uuid;r uuid:=current_setting('qa.entries.recurring')::uuid;e jsonb;
begin
 select public.finance_recurring_terms(x) into e from public.recurring_transactions x where id=r;
 begin perform public.manage_finance_recurring(h,r,'{}',e,true);raise exception 'Archived recurring write accepted';exception when insufficient_privilege then null;end;
 begin update public.goal_contributions set amount=999 where household_id=h;exception when insufficient_privilege then null;end;
 if (select sum(amount) from public.goal_contributions where household_id=h)<>50 then raise exception 'Archived savings mutation accepted';end if;
 begin perform public.manage_finance_recurring(gen_random_uuid(),r,e,e,false);raise exception 'Cross-household accepted';exception when insufficient_privilege then null;end;
end$$;
reset role;
set local role anon;
do $$begin
 begin perform public.manage_finance_recurring(gen_random_uuid(),gen_random_uuid(),'{}','{}',true);raise exception 'Anonymous management accepted';exception when insufficient_privilege then null;end;
 begin perform public.pay_finance_recurring_occurrence(gen_random_uuid(),gen_random_uuid(),100,'2000-01-01');raise exception 'Anonymous payment accepted';exception when insufficient_privilege then null;end;
end$$;
select true as readonly_archive_cross_household_and_anonymous_passed;
rollback;
